import React, { useState, useEffect } from "react";
import { useDispatch } from 'react-redux';
import { setIsFavorite } from "../../store/reducers/modal";

const Favourites = () => {
    const dispatch = useDispatch();
    const [isVisible, setIsVisible] = useState(true);
    const [isBrightening, setIsBrightening] = useState(false);
    const [bgOpacity, setBgOpacity] = useState(0);

    useEffect(() => {
        const darkenTimer = setTimeout(() => {
            setBgOpacity(0.7);
        }, 50);

        const brightenTimer = setTimeout(() => {
            setIsBrightening(true);
            setBgOpacity(0);
        }, 250);

        const finishTimer = setTimeout(() => {
            setIsVisible(false);
        }, 750);

        return () => {
            clearTimeout(darkenTimer);
            clearTimeout(brightenTimer);
            clearTimeout(finishTimer);
        };
    }, []);

    if (!isVisible)
    {
        dispatch(setIsFavorite(false));
        return null;
    } 
        
    return (
        <div className='fixed inset-0 w-full h-auto flex justify-center items-center z-50 overflow-hidden m-0 p-0 box-border'>
            <div
                className="absolute inset-0 bg-black"
                style={{
                    opacity: bgOpacity,
                    transition: 'opacity 200ms ease-out',
                }}
            />
            
            <div className='w-[60%] z-10 font-["Impact",sans-serif] mha-splash-fontSize text-[28px] screen-6:text-[30px] screen-5:text-[38px] sm:text-[47px] md:text-[58px] screen-4:text-[75px] screen-3:text-[90px] screen-2:text-[102px] screen-1:text-[118px] text-splashTx text-center'>
                <p style={{
                    opacity: isBrightening ? 0 : 1,
                    transition: 'opacity 800ms ease-out',
                    willChange: 'opacity',
                }}>
                    FAVORITES
                </p>
            </div>
        </div>
    );
};

export default Favourites;