import React from "react";

const PswChange = () => {
    return (
        <form id="form_changepassword" className="row p-[1rem] mb-[1rem] font-['oxanium']">
            <div className="relative w-full px-[15px]">
                <label for="password" className="m-auto inline-block opacity-[0.8]">Current Password</label>
                <input type="password" style={{ maxWidth: '500px' }} className="block w-full h-[calc(1.5em+0.75rem+2px)] px-3 py-1.5 text-base font-normal leading-6 text-emailTx bg-white border border-emailBd rounded transition-colors duration-150 ease-in-out focus:outline-none focus:ring" />
            </div>
            
            <div className="relative w-full px-[15px]">
                <label for="set_new_password" className="m-auto inline-block opacity-[0.8]">New Password</label>
                <input type="password" style={{ maxWidth: '500px' }} className="block w-full h-[calc(1.5em+0.75rem+2px)] px-3 py-1.5 text-base font-normal leading-6 text-emailTx bg-white border border-emailBd rounded transition-colors duration-150 ease-in-out focus:outline-none focus:ring" />
            </div>
            
            <div className="relative w-full px-[15px]">
                <label for="set_new_password" className="m-auto inline-block opacity-[0.8]">Confirm New Password</label>
                <input type="password" style={{ maxWidth: '500px' }} className="block w-full h-[calc(1.5em+0.75rem+2px)] px-3 py-1.5 text-base font-normal leading-6 text-emailTx bg-white border border-emailBd rounded transition-colors duration-150 ease-in-out focus:outline-none focus:ring" />
            </div>
            
            <div className="flex max-w-[100%] mt-[1rem] px-[15px]">
                <button className="inline-block text-white bg-saveBg border-[1px] border-saveBg px-[0.75rem] py-[0.375rem] rounded-[0.25rem]">SAVE</button>
            </div>
        </form>
    );
};

export default PswChange;